"""Preregistered all-channel persistence gate; reserved B never loaded."""
import argparse
import json
from pathlib import Path
import numpy as np
from data_real_maintenance_002 import FEATURES,write


def ratio_array(model,baseline):
    result=np.divide(model,baseline,out=np.full_like(model,np.nan,dtype=float),where=baseline>0);return np.where((model==0)&(baseline==0),1.,result)


def analyze(directory,output):
    root=Path(directory);summary=json.loads((root/'summary.json').read_text());assert summary['status']=='COMPLETE' and not summary['test_B_opened'];selection=json.loads((root/'selected-arm.json').read_text());chosen=selection['arm'];arms={};rng=np.random.default_rng(93022002)
    for arm in ('linear_static','linear_revin','mlp_static','mlp_revin'):
        reports=[json.loads(p.read_text()) for p in sorted(root.glob(f'group-*/{arm}/report.json'))];tests=[json.loads((root/f"group-{r['seed']}"/arm/'test-a.json').read_text()) for r in reports];assert len(reports)==20;times=np.array(tests[0]['time']);assert all(t['time']==times.tolist() for t in tests);errors=np.array([t['absolute_error'] for t in tests]);baseline=np.array(tests[0]['persistence_absolute_error']);mean_error=errors.mean(0);days=times//86400;unique=np.unique(days);totals=np.stack([mean_error[days==day].sum(0) for day in unique]);naive=np.stack([baseline[days==day].sum(0) for day in unique]);counts=np.array([(days==day).sum() for day in unique]);samples=rng.integers(len(unique),size=(2000,len(unique)));model_mean=totals[samples].sum(1)/counts[samples].sum(1)[:,None];naive_mean=naive[samples].sum(1)/counts[samples].sum(1)[:,None];differences=model_mean-naive_mean;upper=np.quantile(differences,1-.05/8,axis=0);base=baseline.mean(0);pred=mean_error.mean(0);ratios=ratio_array(pred,base);relative_samples=ratio_array(model_mean,naive_mean);improvement=1-ratios.mean();improvement_ci=np.quantile(1-relative_samples.mean(1),[.025,.975]);valid=np.isfinite(ratios).all() and np.isfinite(improvement_ci).all();passing=sum(r['validation']['all_channels_no_worse'] for r in reports);stat_gate=len(unique)>=8 and bool((upper<=0).all());practical=valid and improvement>=.05 and improvement_ci[0]>0
        arms[arm]={'validation_passing_seeds':passing,'test_A_windows':len(times),'test_A_days':len(unique),'channels':[{'name':name,'MAE':float(pred[i]),'persistence_MAE':float(base[i]),'relative_MAE':float(ratios[i]) if np.isfinite(ratios[i]) else None,'difference_upper_simultaneous95':float(upper[i])} for i,name in enumerate(FEATURES)],'mean_defined_channel_relative_MAE':float(np.nanmean(ratios)) if np.isfinite(ratios).any() else None,'defined_relative_MAE_channels':int(np.isfinite(ratios).sum()),'mean_relative_MAE':float(ratios.mean()) if valid else None,'relative_improvement95':[float(v) for v in improvement_ci] if valid else None,'all_channel_no_worse_point':bool((pred<=base).all()),'all_channel_no_worse_simultaneous':stat_gate,'practical_improvement':bool(practical),'per_seed':{str(r['seed']):{'selected_update':r['selected_update'],'validation':r['validation'],'test_A':{k:v for k,v in t.items() if k not in ('absolute_error','persistence_absolute_error','time')}} for r,t in zip(reports,tests,strict=True)}}
    primary=arms[chosen];gates={'validation_18of20':primary['validation_passing_seeds']>=18,'all_analog_no_worse_simultaneous':primary['all_channel_no_worse_simultaneous'],'practical_5percent':primary['practical_improvement']};result={'status':'COMPLETE','run':summary,'chosen_from_validation_only':chosen,'arms':arms,'gates':gates,'advanced_memory_eligible':all(gates.values()),'test_B_opened':False,'decision':'BASELINE_QUALIFIED_NOT_COMMERCIAL' if all(gates.values()) else 'NO_PROMOTION; B remains sealed','scope':'Twenty training initializations on one APU recording; day-cluster bootstrap is not independent fleet evidence. Missing repair actions, costs and independent physical outcomes remain separate gates.'};write(output,result);print('RESULTS',json.dumps({'chosen':chosen,'gates':gates,'decision':result['decision'],'mean_relative_MAE':primary['mean_relative_MAE']}))
    lines=['# REAL-MAINT-002 — persistence-start external sensor qualification','',f"**{result['decision']}**. 80 fresh fits plus 8 validation-only pilots; {summary['fitting_cpu_seconds']:.2f} fitting/preprocessing CPU seconds. Sealed B remains unopened.",'',f'Primary arm selected from validation: **{chosen}**. No arm was selected from A outcomes.','', '| Arm | Validation seed passes | Mean relative MAE on A | All-channel simultaneous gate |','|---|---:|---:|---|']
    for arm,v in arms.items():lines.append(f"| {arm} | {v['validation_passing_seeds']}/20 | {v['mean_relative_MAE']} | {v['all_channel_no_worse_simultaneous']} |")
    lines+=['','| Primary channel | Raw MAE | Persistence MAE | Relative MAE | Simultaneous upper difference |','|---|---:|---:|---:|---:|']
    for v in primary['channels']:lines.append(f"| {v['name']} | {v['MAE']:.6g} | {v['persistence_MAE']:.6g} | {v['relative_MAE']} | {v['difference_upper_simultaneous95']:.6g} |")
    lines+=['','MASE uses TRAIN persistence error as scale; full per-channel MASE, undefined scales, every seed and raw errors remain in the [statistics](statistics.json) and indexed evidence. Ratios here divide by A persistence MAE for descriptive comparison; this denominator is never used for training. The simultaneous gate uses 2000 paired day-block bootstrap resamples with Bonferroni8.','', 'Data: [MetroPT2, Zenodo](https://zenodo.org/records/7766691), CC BY4.0, creators Veloso/Gama/Ribeiro/Pereira. This 2022 recording is distinct from the opened 2020 MetroPT-3 study. A is June15–30; B is July onward and stays unopened. Source metadata dates are public; numerical B evaluation remains prohibited by this registration.','', 'No advanced memory comparison, commercial repair policy, cost saving, foundation-model or universal hardware claim follows. Only eight predeclared analog channels are evaluated; digital/GPS were excluded before fitting. Original REAL001 failures remain in the [retrospective diagnostic](retrospective-001.json).']
    Path(output).with_name('RESULTS.md').write_text('\n'.join(lines)+'\n')


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--directory',required=True);p.add_argument('--output',required=True);a=p.parse_args();analyze(a.directory,a.output)
